-- Every line of the four recorded works on Ghāfir 40:1–3 in accurate English, with the registry
-- terms each line uses (qr_tafsir_segment_en, qr_070): al-Rāzī lines 1–136 (to where he turns to
-- 40:4), al-Ālūsī 1–142, Ibn ʿĀshūr 1–54, al-Zamakhsharī 1–65. Rendered line by line so the lines
-- read in order make one continuous translation; technical terms in English with the Arabic in
-- Arabic script, never transliterated. Terms resolved by exact lookup in ar_ling_gram_term /
-- ar_ling_gram_term_alias; a term the registry does not hold is not linked.
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:1', 'QRTA:razi:40-01', 1, '(سورة غافر, “The Forgiver”) Eighty-five verses, Meccan. In the name of God, the Most Merciful, the Most Compassionate. “حم.” “The revelation of the Book is from God, the Almighty, the All-Knowing,” “Forgiver of sin and Accepter of repentance,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:2', 'QRTA:razi:40-01', 2, 'Severe in punishment, Possessor of bounty; there is no god but He; to Him is the final return.” “None dispute concerning the signs of God except those who disbelieve,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:3', 'QRTA:razi:40-01', 3, 'so do not let their going to and fro in the lands deceive you.” “Before them the people of Noah denied, and the factions after them, and every nation resolved against its messenger to seize him, and they disputed', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:4', 'QRTA:razi:40-01', 4, 'with falsehood to refute the truth by it; so I seized them, and how was My punishment!” “And thus the word of your Lord has come true against those who disbelieved: that they are the companions of the Fire.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:5', 'QRTA:razi:40-01', 5, 'In the name of God, the Most Merciful, the Most Compassionate. “حم.” “The revelation of the Book is from God, the Almighty, the All-Knowing,” “Forgiver of sin and Accepter of repentance, Severe in punishment, Possessor of bounty; there is no god', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:6', 'QRTA:razi:40-01', 6, 'but He; to Him is the final return.” “None dispute concerning the signs of God except those who disbelieve, so do not let their going to and fro in the lands deceive you.” “There denied,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:7', 'QRTA:razi:40-01', 7, 'before them, the people of Noah, and the factions after them, and every nation resolved against its messenger to seize him, and they disputed with falsehood to refute the truth by it; so I seized them, and how', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:8', 'QRTA:razi:40-01', 8, 'was My punishment!” “And thus the word of your Lord has come true against those who disbelieved: that they are the companions of the Fire.” Know that in this verse there are several questions:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:9', 'QRTA:razi:40-01', 9, 'The first question: ʿĀṣim in the transmission of Abū Bakr, and Ḥamza and al-Kisāʾī read “حم” with the vowel i on the letter ح, and the rest with the vowel a on the ح; and Nāfiʿ in some transmissions', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:10', 'QRTA:razi:40-01', 10, 'and Ibn ʿĀmir read it between the a and the i (بين الفتح والكسر), which is not opening it with a full a. The author of al-Kashshāf said:', '[{"ar": "بَيْنَ الفَتْحِ والكَسْرِ", "ref": "GT:phonotactic:imala"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:11', 'QRTA:razi:40-01', 11, 'it has been read with the vowel a on the letter م and with the م vowelless. The reason for the a is that a vowel is given because two vowelless letters meet (التقاء الساكنين), with preference for the lightest of the vowels, as in', '[{"ar": "لِالتِقاءِ السّاكِنَيْنِ", "ref": "GT:phonotactic:iltiqa_sakinayn"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:12', 'QRTA:razi:40-01', 12, 'أين (“where”) and كيف (“how”); or it is the accusative (النصب) by an implied (إضمار) “recite”; and its being barred from full declension (منع الصرف) is either because of feminine gender (التأنيث) and definiteness (التعريف), in that it is a name of the surah, or because of definiteness and its being', '[{"ar": "النَّصْبِ", "ref": "GT:case:accusative"}, {"ar": "إضْمارِ", "ref": "GT:irab_role:idmar_al_amil"}, {"ar": "مَنعُ الصَّرْفِ", "ref": "GT:noun_process:man_al_sarf"}, {"ar": "لِلتَّأْنِيثِ", "ref": "GT:gender:feminine"}, {"ar": "التَّعْرِيفِ", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:13', 'QRTA:razi:40-01', 13, 'on the pattern of a foreign word, such as قابيل (Cain) and هابيل (Abel). As for the vowelless reading (السكون), it is because we have shown that these names are uttered with their endings in pause (موقوفة الأواخر).', '[{"ar": "السُّكُونُ", "ref": "GT:irab_sign:sukun"}, {"ar": "مَوْقُوفَةَ الأواخِرِ", "ref": "GT:phonotactic:waqf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:14', 'QRTA:razi:40-01', 14, 'The second question: the exhaustive discussion of these opening letters (الفواتح) is given at the beginning of Surah al-Baqara. What is most likely here is to say:', '[{"ar": "الفَواتِحِ", "ref": "GT:harf_maani:muqattaa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:15', 'QRTA:razi:40-01', 15, '“حم” is a name of the surah; so His saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:16', 'QRTA:razi:40-01', 16, '“حم” is a subject (مبتدأ), and His saying:', '[{"ar": "مُبْتَدَأٌ", "ref": "GT:irab_role:mubtada"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:17', 'QRTA:razi:40-01', 17, '“The revelation of the Book from God” is a predicate (خبر); the underlying sense (التقدير) is that this surah named حم is the revelation of the Book. So His saying:', '[{"ar": "خَبَرٌ", "ref": "GT:irab_role:khabar"}, {"ar": "التَّقْدِيرُ", "ref": "GT:irab_role:taqdir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:18', 'QRTA:razi:40-01', 18, '“revelation” is a verbal noun (مصدر), but what is meant by it is the thing revealed.', '[{"ar": "مَصْدَرٌ", "ref": "GT:derivation_type:masdar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:19', 'QRTA:razi:40-01', 19, 'As for His saying “from God,” know that when He had stated that “حم” is “the revelation of the Book,” it became necessary to make clear who the One who sends it down is.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:20', 'QRTA:razi:40-01', 20, 'So He said: “from God.” Then He made clear that God Most High is described by attributes of majesty and marks of grandeur, so that this would spur one to roll up one''s sleeves', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:21', 'QRTA:razi:40-01', 21, 'in earnest when listening, and deter one from carelessness and slackness in it; so He made clear that the One who sends it down is “God, the Almighty, the All-Knowing.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:22', 'QRTA:razi:40-01', 22, 'And know that people have differed over what knowledge of God is.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:23', 'QRTA:razi:40-01', 23, 'A great many said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:24', 'QRTA:razi:40-01', 24, 'it is knowledge of His being powerful, and after it knowledge of His being knowing. Once you know this, we say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:25', 'QRTA:razi:40-01', 25, '“The Almighty” has two interpretations:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:26', 'QRTA:razi:40-01', 26, 'the first is “the overpowering,” so that its meaning is the Powerful whom no one equals in power;', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:27', 'QRTA:razi:40-01', 27, 'the second is the one who has no like. It cannot be that what is meant by “the Almighty” here is the Powerful,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:28', 'QRTA:razi:40-01', 28, 'because His saying, Exalted is He:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:29', 'QRTA:razi:40-01', 29, '“God” indicates His being powerful; so “the Almighty” must be taken in the second meaning, namely the one for whom no like exists. And whatever', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:30', 'QRTA:razi:40-01', 30, 'is such must not be a body; and what is not a body is free of desire and aversion; and what is', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:31', 'QRTA:razi:40-01', 31, 'such is free of need.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:32', 'QRTA:razi:40-01', 32, 'As for “the All-Knowing,” it is an intensive form (مبالغة) of knowledge, and complete intensiveness is realised only when He, Exalted is He, knows all that can be known. So His saying', '[{"ar": "مُبالَغَةٌ", "ref": "GT:derivation_type:mubalagha"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:33', 'QRTA:razi:40-01', 33, '“from God, the Almighty, the All-Knowing” comes down in meaning to this: that this Book is a revelation from the absolutely Powerful, the absolutely Self-Sufficient, the absolutely Knowing;', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:34', 'QRTA:razi:40-01', 34, 'and whoever is such knows the ways of what benefits and what corrupts, and knows that He has no need of procuring benefits or warding off harms; and whoever', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:35', 'QRTA:razi:40-01', 35, 'is such is merciful and generous, and His acts are wisdom and rightness, free of the ugly and the false. So it is as though He, Glorified is He, mentioned right after', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:36', 'QRTA:razi:40-01', 36, 'His saying “revelation” these three names only because they indicate that His acts, Glorified is He, are wisdom and rightness; and when the matter is so, it follows necessarily that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:37', 'QRTA:razi:40-01', 37, 'this revelation is true and right. And it has been said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:38', 'QRTA:razi:40-01', 38, 'the benefit of mentioning “the Almighty, the All-Knowing” is two things:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:39', 'QRTA:razi:40-01', 39, 'first, that by His power and His knowledge He sent down the Qurʾān in this manner, which comprises what is beneficial and inimitability; had He not been almighty and all-knowing, that would not have been', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:40', 'QRTA:razi:40-01', 40, 'possible. Second, that He took it upon Himself to preserve it, to make the obligations in it universal, and to keep it manifest until religious obligation comes to an end; and that is achieved only by His being almighty, never', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:41', 'QRTA:razi:40-01', 41, 'overcome, and by His being all-knowing, from whom nothing is hidden. Then He described Himself with what combines promise and threat, deterrence (الترهيب) and encouragement (الترغيب), saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:42', 'QRTA:razi:40-01', 42, '“Forgiver of sin and Accepter of repentance, Severe in punishment, Possessor of bounty; there is no god but He; to Him is the final return.” These, then, are six kinds of', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:43', 'QRTA:razi:40-01', 43, 'attributes. The first attribute:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:44', 'QRTA:razi:40-01', 44, 'His saying “Forgiver of sin.” Al-Jubbāʾī said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:45', 'QRTA:razi:40-01', 45, 'its meaning is that He is the Forgiver of sin when its forgiveness has been earned, either by repentance or by an act of obedience greater than it. What he means by this is that, regarding the one who commits a sin,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:46', 'QRTA:razi:40-01', 46, 'either it is said', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:47', 'QRTA:razi:40-01', 47, 'that he had previously performed an act of obedience whose reward was greater than the punishment of this sin, or the matter was not', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:48', 'QRTA:razi:40-01', 48, 'so. If the first, this sin is a minor one, and its punishment is cancelled; if the second, this sin is a major one, and its punishment does not', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:49', 'QRTA:razi:40-01', 49, 'go away except by repentance.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:50', 'QRTA:razi:40-01', 50, 'The position of our school is that God Most High may pardon a major sin after repentance [so the printed text reads; the proofs that follow argue for pardon before repentance], and this verse indicates that. The explanation of this is from', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:51', 'QRTA:razi:40-01', 51, 'several angles. The first: forgiving a major sin after repentance and forgiving a minor sin are among the things obligatory upon the servant, and all the prophets, the saints and the righteous among ordinary', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:52', 'QRTA:razi:40-01', 52, 'people share in doing what is obligatory. So if we took His being Forgiver of sin in this sense, there would remain between Him and', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:53', 'QRTA:razi:40-01', 53, 'the least of people in the company of the obedient no difference in the meaning that warrants this praise, and that is false. So it is established that it must be that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:54', 'QRTA:razi:40-01', 54, 'what is meant by it is His being the Forgiver of major sins before repentance, and that is what was to be proved.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:55', 'QRTA:razi:40-01', 55, 'The second: forgiveness means covering, and the meaning of covering is intelligible only for a thing that remains existent and is then covered; but a minor sin is cancelled', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:56', 'QRTA:razi:40-01', 56, 'because of the abundance of its doer''s reward, so the meaning of forgiving is unintelligible in its case. Nor can His saying', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:57', 'QRTA:razi:40-01', 57, '“Forgiver of sin” be taken to refer to a major sin after repentance,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:58', 'QRTA:razi:40-01', 58, 'because the meaning of His being Accepter of repentance is nothing but that; so if what were meant by His being Forgiver of sin were this meaning, repetition would follow,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:59', 'QRTA:razi:40-01', 59, 'and that is false. So it is established that His being Forgiver of sin conveys His being Forgiver of major sins before repentance.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:60', 'QRTA:razi:40-01', 60, 'The third: His saying', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:61', 'QRTA:razi:40-01', 61, '“Forgiver of sin” is mentioned in the setting of great praise, so it must be taken to mean what conveys the greatest kind of praise, and that is His being', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:62', 'QRTA:razi:40-01', 62, 'Forgiver of major sins before repentance, and that is what was to be proved.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:63', 'QRTA:razi:40-01', 63, 'The second attribute: His saying, Exalted is He:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:64', 'QRTA:razi:40-01', 64, '“Accepter of repentance.” In it there are two discussions:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:65', 'QRTA:razi:40-01', 65, 'The first: on the word التوب there are two views:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:66', 'QRTA:razi:40-01', 66, 'the first, that it is a verbal noun (مصدر); this is the view of Abū ʿUbayda.', '[{"ar": "مَصْدَرٌ", "ref": "GT:derivation_type:masdar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:67', 'QRTA:razi:40-01', 67, 'The second, that it is the plural of توبة; this is the view of al-Akhfash.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:68', 'QRTA:razi:40-01', 68, 'Al-Mubarrad said: it may be a verbal noun (مصدر); one says:', '[{"ar": "مَصْدَرًا", "ref": "GT:derivation_type:masdar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:69', 'QRTA:razi:40-01', 69, 'تاب يتوب توبًا وتوبة (he repented), just as قال يقول قولًا وقولة (he said); and it may be a plural (جمع) of توبة, so that there is', '[{"ar": "جَمْعًا", "ref": "GT:number:plural"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:70', 'QRTA:razi:40-01', 70, 'توبة and توب, like تمرة and تمر (a date, dates). But the verbal noun (المصدر) is more likely, because on this assumption its interpretation is that He accepts this', '[{"ar": "المَصْدَرَ", "ref": "GT:derivation_type:masdar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:71', 'QRTA:razi:40-01', 71, 'act. The second: the position of our school is that the acceptance of repentance from the sinner happens by way of grace, and is not obligatory upon God, while the Muʿtazila said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:72', 'QRTA:razi:40-01', 72, 'it is obligatory upon God. Our school argued that He, Exalted is He, mentioned His being Accepter of repentance by way of praise and commendation; and if', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:73', 'QRTA:razi:40-01', 73, 'that were among obligations, there would remain in it of the meaning of praise only a little, namely the measure that all righteous people attain when', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:74', 'QRTA:razi:40-01', 74, 'performing obligations and guarding against what is prohibited.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:75', 'QRTA:razi:40-01', 75, 'The third attribute: His saying “Severe in punishment.” In it there are several discussions:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:76', 'QRTA:razi:40-01', 76, 'The first discussion: in this verse there is a question, namely that His saying', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:77', 'QRTA:razi:40-01', 77, '“Severe in punishment” is fit to be an attributive adjective (نعت) of an indefinite noun (النكرة) and not fit to be an attributive adjective of a definite noun (المعرفة). You say:', '[{"ar": "نَعْتًا", "ref": "GT:irab_role:naat"}, {"ar": "لِلنَّكِرَةِ", "ref": "GT:definiteness:indefinite"}, {"ar": "لِلْمَعْرِفَةِ", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:78', 'QRTA:razi:40-01', 78, '“I passed by a man severe in assault,” but you do not say “I passed by ʿAbd Allāh, severe in assault.” And His word', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:79', 'QRTA:razi:40-01', 79, '“God” is a proper name (اسم علم), so it is definite (معرفة); how then is it allowed to describe Him as severe in punishment, when that is only fit to be made', '[{"ar": "اسْمُ عَلَمٍ", "ref": "GT:pos:alam"}, {"ar": "مَعْرِفَةً", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:80', 'QRTA:razi:40-01', 80, 'an attribute (وصف) of an indefinite noun (النكرة)? They said:', '[{"ar": "وصْفًا", "ref": "GT:irab_role:naat"}, {"ar": "لِلنَّكِرَةِ", "ref": "GT:definiteness:indefinite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:81', 'QRTA:razi:40-01', 81, 'And this is unlike our saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:82', 'QRTA:razi:40-01', 82, '“Forgiver of sin and Accepter of repentance,”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:83', 'QRTA:razi:40-01', 83, 'because what is meant by these two is not the occurrence of these two acts, that He forgives sin and accepts repentance now or tomorrow; rather, what is meant is that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:84', 'QRTA:razi:40-01', 84, 'this is fixed and permanent, so their status is the status of “God of creation” and “Lord of the Throne.” But “Severe in punishment” is problematic,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:85', 'QRTA:razi:40-01', 85, 'because it is in the underlying form (تقدير) of:', '[{"ar": "تَقْدِيرِ", "ref": "GT:irab_role:taqdir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:86', 'QRTA:razi:40-01', 86, '“شديدٌ عقابُه” (one whose punishment is severe), so it is indefinite (نكرة), and it is not valid to make it an attribute (صفة) of a definite noun (المعرفة). This is the statement of the question, and it has been answered in several ways:', '[{"ar": "نَكِرَةً", "ref": "GT:definiteness:indefinite"}, {"ar": "صِفَةً", "ref": "GT:pos:sifa"}, {"ar": "لِلْمَعْرِفَةِ", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:87', 'QRTA:razi:40-01', 87, 'The first: this attribute (الصفة), even though it is indefinite (نكرة), yet since it was mentioned together with the other attributes, which are definite (معارف), mentioning it was acceptable,', '[{"ar": "الصِّفَةَ", "ref": "GT:pos:sifa"}, {"ar": "نَكِرَةً", "ref": "GT:definiteness:indefinite"}, {"ar": "مَعارِفُ", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:88', 'QRTA:razi:40-01', 88, 'as in His saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:89', 'QRTA:razi:40-01', 89, '“And He is the Forgiving, the Loving, Owner of the Throne, the Glorious, Doer of whatever He wills” [al-Burūj:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:90', 'QRTA:razi:40-01', 90, '14–16]. The second: al-Zajjāj said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:91', 'QRTA:razi:40-01', 91, 'the genitive (خفض) of “Severe in punishment” is as a substitute (البدل),', '[{"ar": "خَفْضَ", "ref": "GT:case:genitive"}, {"ar": "البَدَلِ", "ref": "GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:92', 'QRTA:razi:40-01', 92, 'because making an indefinite noun (النكرة) a substitute (بدل) for a definite noun (المعرفة), and the reverse, is permissible. They objected to him that making it alone, among the attributes (الصفات), a substitute has in it', '[{"ar": "النَّكِرَةِ", "ref": "GT:definiteness:indefinite"}, {"ar": "بَدَلًا", "ref": "GT:irab_role:badal"}, {"ar": "المَعْرِفَةِ", "ref": "GT:definiteness:definite"}, {"ar": "الصِّفاتِ", "ref": "GT:pos:sifa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:93', 'QRTA:razi:40-01', 93, 'an obvious incongruity. The third:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:94', 'QRTA:razi:40-01', 94, 'there is no dispute that His saying', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:95', 'QRTA:razi:40-01', 95, '“Forgiver of sin and Accepter of repentance” may properly be made attributes (صفة), and that was so only because they convey the meaning of permanence and continuity; likewise His saying', '[{"ar": "صِفَةً", "ref": "GT:pos:sifa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:96', 'QRTA:razi:40-01', 96, '“Severe in punishment” conveys the meaning of permanence and continuity,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:97', 'QRTA:razi:40-01', 97, 'because the attributes of God Most High are free of coming-to-be and renewal; so His being severe in punishment means His being such that His punishment is severe, and this meaning', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:98', 'QRTA:razi:40-01', 98, 'holds forever and is not described as having come about after it was not so. This is what has been said on this subject.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:99', 'QRTA:razi:40-01', 99, 'The second discussion: this verse suggests that the side of mercy and grace prevails,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:100', 'QRTA:razi:40-01', 100, 'because when He, Exalted is He, wished to describe Himself as severe in punishment, He mentioned before it two things, each of which requires the removal', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:101', 'QRTA:razi:40-01', 101, 'of punishment, namely His being Forgiver of sin and Accepter of repentance; and He mentioned after it what indicates the attainment of great mercy, namely His saying', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:102', 'QRTA:razi:40-01', 102, '“Possessor of bounty.” So since His being severe in punishment is preceded by those two attributes and followed by this attribute, that indicates that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:103', 'QRTA:razi:40-01', 103, 'the side of mercy and generosity is weightier.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:104', 'QRTA:razi:40-01', 104, 'The third discussion: someone may say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:105', 'QRTA:razi:40-01', 105, 'He mentioned the “and” (الواو) in His saying', '[{"ar": "الواوَ", "ref": "GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:106', 'QRTA:razi:40-01', 106, '“Forgiver of sin and Accepter of repentance,” but did not mention it in His saying', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:107', 'QRTA:razi:40-01', 107, '“Severe in punishment”; so what is the difference?', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:108', 'QRTA:razi:40-01', 108, 'We say: had He not mentioned the “and” (الواو) in His saying', '[{"ar": "الواوَ", "ref": "GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:109', 'QRTA:razi:40-01', 109, '“Forgiver of sin and Accepter of repentance,” it would have been possible for it to occur to someone''s mind that His being Forgiver of sin means nothing other than His being', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:110', 'QRTA:razi:40-01', 110, 'Accepter of repentance; but since He mentioned the “and” (الواو), this possibility is removed,', '[{"ar": "الواوَ", "ref": "GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:111', 'QRTA:razi:40-01', 111, 'because coordinating (عطف) a thing upon itself is impossible. As for His being severe in punishment, it is known that it differs from His being “Forgiver of sin and Accepter of repentance,”', '[{"ar": "عَطْفَ", "ref": "GT:irab_role:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:112', 'QRTA:razi:40-01', 112, 'so He could do without mentioning the “and” (الواو).', '[{"ar": "الواوِ", "ref": "GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:113', 'QRTA:razi:40-01', 113, 'The fourth attribute: “Possessor of bounty,” that is, Possessor of favour. One says:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:114', 'QRTA:razi:40-01', 114, 'طال علينا طولًا (he bestowed bounty on us),', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:115', 'QRTA:razi:40-01', 115, 'that is, he showed us favour; and among their expressions is:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:116', 'QRTA:razi:40-01', 116, 'طُلْ عليَّ بفضلك (bestow your bounty upon me); and from this is His saying, Exalted is He:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:117', 'QRTA:razi:40-01', 117, '“those of means among them” [al-Tawba:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:118', 'QRTA:razi:40-01', 118, '86]; and its interpretation has already passed at His saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:119', 'QRTA:razi:40-01', 119, '“And whoever among you cannot afford the means” [al-Nisāʾ:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:120', 'QRTA:razi:40-01', 120, '25]. And know that, since He described Himself as being “Severe in punishment,” what is meant must be His being One who brings the punishment', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:121', 'QRTA:razi:40-01', 121, 'that is severe, His bringing of which is not ugly on His part; indeed, it is not permissible to describe Him, Exalted is He, as doing what is ugly. Once this is established,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:122', 'QRTA:razi:40-01', 122, 'we say: after it He mentioned His being Possessor of bounty, which is His being Possessor of favour; so its meaning must be His being Possessor of favour by reason of His', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:123', 'QRTA:razi:40-01', 123, 'forgoing the punishment that He is entitled to inflict,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:124', 'QRTA:razi:40-01', 124, 'because He mentioned His being Possessor of bounty without making clear in what He is Possessor of bounty; so it must be referred to His being Possessor of bounty', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:125', 'QRTA:razi:40-01', 125, 'in the matter mentioned just before, namely the inflicting of punishment that is good, so as to remove the vagueness (الإجمال). And this indicates that He, Exalted is He, may forgo', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:126', 'QRTA:razi:40-01', 126, 'the punishment whose inflicting would be good on His part; and that indicates that pardon for those who commit major sins is possible, and that is what was to be proved.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:127', 'QRTA:razi:40-01', 127, 'The fifth attribute: the absolute affirmation of His oneness, and it is His saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:128', 'QRTA:razi:40-01', 128, '“There is no god but He.” The meaning is that He described Himself with attributes of mercy and favour; so if there were with Him another god sharing with Him and equal to Him', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:129', 'QRTA:razi:40-01', 129, 'in the attribute of mercy and favour, the need to serve Him would not be acute; but if He is one, having no partner and no', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:130', 'QRTA:razi:40-01', 130, 'likeness, the need to acknowledge servitude to Him is acute; so complete encouragement (الترغيب) and deterrence (الترهيب) come about through this affirmation of oneness.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:131', 'QRTA:razi:40-01', 131, 'The sixth attribute: His saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:132', 'QRTA:razi:40-01', 132, '“To Him is the final return.” This attribute too is among what strengthens the desire to acknowledge servitude to Him,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:133', 'QRTA:razi:40-01', 133, 'because, supposing He were described by attributes of favour and generosity and were one with no partner, yet if the doctrine of the gathering and the raising of the dead', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:134', 'QRTA:razi:40-01', 134, 'were false, intense fear of disobeying Him would not arise; but since the doctrine of the gathering and the Resurrection holds, the', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:135', 'QRTA:razi:40-01', 135, 'fear is greater and the caution more complete. For this reason God Most High mentioned these attributes. The anthropomorphists (أهل التشبيه) argued from the word “to” (إلى), saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:razi:40-01:136', 'QRTA:razi:40-01', 136, 'it conveys the end-point of a limit (انتهاء الغاية). The answer to this is given in many places in this book.', '[{"ar": "انْتِهاءَ الغايَةِ", "ref": "GT:harf_maani:ila_intiha_ghaya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:1', 'QRTA:alusi:40-01', 1, 'The Surah of the Believer (المؤمن), which is also called the Surah of the Forgiver (غافر) and the Surah of Bounty (الطول). According to what is reported from Ibn ʿAbbās, Ibn al-Zubayr, Masrūq and Samura ibn', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:2', 'QRTA:alusi:40-01', 2, 'Jundub, it is Meccan (مكية), and Abū Ḥayyān reported a consensus on this. From al-Ḥasan it is reported that it is Meccan except for His saying, Exalted is He:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:3', 'QRTA:alusi:40-01', 3, '“And glorify [Him] with the praise of your Lord” [The Forgiver (غافر):', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:4', 'QRTA:alusi:40-01', 4, '55], because the prayers were revealed in Medina, whereas prayer in Mecca had been two cycles (ركعتين) without set times.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:5', 'QRTA:alusi:40-01', 5, 'But you know that the truth is the view of the majority:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:6', 'QRTA:alusi:40-01', 6, 'that the five [prayers] were revealed in Mecca; moreover, it is not certain that prayer is what is meant by ‘glorification’ in the verse. It has also been said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:7', 'QRTA:alusi:40-01', 7, 'It is Meccan except for His saying, Exalted is He:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:8', 'QRTA:alusi:40-01', 8, '“Those who dispute” [The Forgiver (غافر):', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:9', 'QRTA:alusi:40-01', 9, '35] — the verse — for it is Medinan (مدنية): Ibn Abī Ḥātim reported from Abū al-ʿĀliya and others that it was revealed concerning the Jews when', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:10', 'QRTA:alusi:40-01', 10, 'they mentioned the Antichrist (الدجال). Yet this is not an explicit statement that it was revealed in Medina. The Shaykh of Islam, Ibn Taymiyya, said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:11', 'QRTA:alusi:40-01', 11, '“Their saying ‘the verse was revealed concerning such-and-such’ sometimes means the occasion of revelation (سبب النزول), and sometimes means that this is included in the verse,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:12', 'QRTA:alusi:40-01', 12, 'even if it was not the occasion, as when you say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:13', 'QRTA:alusi:40-01', 13, '‘By this verse such-and-such is meant.’” And al-Zarkashī said in al-Burhān:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:14', 'QRTA:alusi:40-01', 14, '“It is known from the practice of the Companions and the Successors that when one of them says', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:15', 'QRTA:alusi:40-01', 15, '‘the verse was revealed concerning such-and-such’, he means by it that the verse contains this ruling, not that this was the cause of its revelation;', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:16', 'QRTA:alusi:40-01', 16, 'so it belongs to the kind of drawing a ruling from the verse as evidence, not to the kind of reporting what took place.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:17', 'QRTA:alusi:40-01', 17, 'Admittedly, there will come later, God Most High willing, a report from Abū al-ʿĀliya that is almost an explicit statement of that.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:18', 'QRTA:alusi:40-01', 18, 'Its verses number eighty-five in the Kufan and Syrian counts, eighty-four in the Hijazi, and eighty-two in the Basran; it has also been said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:19', 'QRTA:alusi:40-01', 19, 'eighty-six; and it has been said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:20', 'QRTA:alusi:40-01', 20, 'eighty-eight. The connection (مناسبة) of its opening with the end of the Throngs (الزمر) is that when He, Exalted and Glorified, mentioned there what the state of the unbeliever comes to', '[{"ar":"مُناسِبَةِ","ref":"GT:balagha_maani:munasaba"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:21', 'QRTA:alusi:40-01', 21, 'and the state of the believer, He, Majestic and Exalted, mentioned here that He is “Forgiver of sin and Accepter of repentance,” so that this would be a summons to the unbeliever to faith', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:22', 'QRTA:alusi:40-01', 22, 'and to giving up what he is engaged in. Between the two surahs themselves there are several aspects of connection (المناسبة), and it suffices among them that in each there is mentioned, concerning the conditions of', '[{"ar":"المُناسَبَةِ","ref":"GT:balagha_maani:munasaba"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:23', 'QRTA:alusi:40-01', 23, 'the Day of Resurrection and the conditions of the unbelievers on it, while they are at the place of gathering and in the Fire, what is mentioned; and in this surah some of that is set out in detail', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:24', 'QRTA:alusi:40-01', 24, 'that was not set out in detail in that one.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:25', 'QRTA:alusi:40-01', 25, 'In Tanāsuq al-Durar [it is said]: the reason for placing the seven surahs that open with حم (الحواميم) after the Surah of the Throngs is the kinship of their openings, in beginning with the sending down of the Book.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:26', 'QRTA:alusi:40-01', 26, 'And in the codex of Ibn Masʿūd the beginning of the Throngs is حم, and that is a splendid connection (مناسبة). Moreover, the حم surahs were placed in sequence because they share in opening —', '[{"ar":"مُناسَبَةٌ","ref":"GT:balagha_maani:munasaba"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:27', 'QRTA:alusi:40-01', 27, 'with حم — and in mentioning the Book, and in being Meccan; indeed, it is reported from Ibn ʿAbbās and Jābir ibn Zayd that they were revealed after the Throngs,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:28', 'QRTA:alusi:40-01', 28, 'one after another, in the same order as in the codex. Many reports have come down about their merit. Abū ʿUbayd reported in his Faḍāʾil from Ibn ʿAbbās, who said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:29', 'QRTA:alusi:40-01', 29, '“Everything has a kernel, and the kernel of the Qurʾān is the حم surahs.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:30', 'QRTA:alusi:40-01', 30, 'And he, Ibn al-Ḍurays, Ibn al-Mundhir, al-Ḥākim, and al-Bayhaqī in Shuʿab al-Īmān reported from Ibn Masʿūd, who said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:31', 'QRTA:alusi:40-01', 31, '“The حم surahs are the brocade of the Qurʾān.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:32', 'QRTA:alusi:40-01', 32, 'Abū al-Shaykh, Abū Nuʿaym and al-Daylamī reported it from Anas, may God Most High be pleased with him, traced back to the Prophet (مرفوعًا); and al-Daylamī and Ibn Mardawayh reported from', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:33', 'QRTA:alusi:40-01', 33, 'Samura ibn Jundub, traced back to the Prophet: “The حم surahs are a meadow among the meadows of Paradise.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:34', 'QRTA:alusi:40-01', 34, 'Muḥammad ibn Naṣr and al-Dārimī reported from Saʿd ibn Ibrāhīm, who said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:35', 'QRTA:alusi:40-01', 35, '“The حم surahs used to be called ‘the brides’.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:36', 'QRTA:alusi:40-01', 36, 'Ibn Naṣr and Ibn Mardawayh reported from Anas ibn Mālik, who said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:37', 'QRTA:alusi:40-01', 37, '“I heard the Messenger of God, may God Most High bless him and grant him peace, say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:38', 'QRTA:alusi:40-01', 38, '‘God Most High gave me the seven long surahs in place of the Torah; He gave me the surahs opening with الر (الراءات) up to the surahs opening with طس (الطواسين) in place of the Gospel; and He gave me what lies between the طس surahs', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:39', 'QRTA:alusi:40-01', 39, 'and the حم surahs in place of the Psalms; and He favoured me with the حم surahs and the short, closely divided surahs (المفصل), which no prophet before me recited.’”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:40', 'QRTA:alusi:40-01', 40, 'Al-Bayhaqī reported in al-Shuʿab from al-Khalīl ibn Murra that the Messenger of God, may God bless him and grant him peace, said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:41', 'QRTA:alusi:40-01', 41, '“The حم surahs are seven, and the gates of Hell are seven. Each حم of them will come and stand at one of these gates, saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:42', 'QRTA:alusi:40-01', 42, '‘O God, do not let anyone who used to believe in me and recite me enter through this gate.’” And concerning certain particular verses of this', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:43', 'QRTA:alusi:40-01', 43, 'surah, there have come reports indicating their merit.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:44', 'QRTA:alusi:40-01', 44, 'Al-Tirmidhī, al-Bazzār, Muḥammad ibn Naṣr, Ibn Mardawayh, and al-Bayhaqī in al-Shuʿab reported from Abū Hurayra, who said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:45', 'QRTA:alusi:40-01', 45, '“The Messenger of God, may God bless him and grant him peace, said: ‘Whoever recites حم up to “to Him is the final return” together with the Throne Verse when he enters the morning will be protected by them until he enters the evening,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:46', 'QRTA:alusi:40-01', 46, 'and whoever recites them when he enters the evening will be protected by them until he enters the morning.’”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:47', 'QRTA:alusi:40-01', 47, '(In the name of God, the Most Merciful, the Most Compassionate) «حم»: read with full, unslanted articulation (تفخيم) of the ا and with the م made quiescent (تسكين). Ibn ʿĀmir in the transmission of Dhakwān, Ḥamza, al-Kisāʾī', '[{"ar":"تَسْكِينِ","ref":"GT:irab_sign:sukun"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:48', 'QRTA:alusi:40-01', 48, 'and Abū Bakr read it with full inclination of the vowel toward i (الإمالة الصريحة); and Nāfiʿ in the transmission of Warsh', '[{"ar":"الإمالَةِ","ref":"GT:phonotactic:imala"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:49', 'QRTA:alusi:40-01', 49, 'and Abū ʿAmr with inclination halfway, ‘between the two’ (الإمالة بين بين). Ibn Abī Isḥāq and ʿĪsā read it with an a-vowel on the م (فتح), as a vowelling [printed التحريم, read التحريك] because two quiescent letters meet (التقاء الساكنين), [choosing] the a-vowel (الفتحة) for lightness,', '[{"ar":"الإمالَةِ","ref":"GT:phonotactic:imala"},{"ar":"فَتْحِ","ref":"GT:irab_sign:fatha"},{"ar":"التِقاءِ السّاكِنَيْنِ","ref":"GT:phonotactic:iltiqa_sakinayn"},{"ar":"الفَتْحَةِ","ref":"GT:irab_sign:fatha"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:50', 'QRTA:alusi:40-01', 50, 'as in أين and كيف. It has also been allowed that this is an accusative (نصب) by an implied (إضمار) ‘recite’, and that it is barred from full declension (منع من الصرف) because of proper-name status (العلمية) and femininity (التأنيث), since it means', '[{"ar":"نَصْبًا","ref":"GT:case:accusative"},{"ar":"إضْمارِ","ref":"GT:irab_role:idmar_al_amil"},{"ar":"مُنِعَ مِنَ الصَّرْفِ","ref":"GT:noun_process:man_al_sarf"},{"ar":"التَّأْنِيثِ","ref":"GT:gender:feminine"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:51', 'QRTA:alusi:40-01', 51, '‘the surah’; or because of proper-name status and quasi-foreignness (شبه العجمة), since the pattern فاعيل is not one of the patterns of Arab word-forms; it is found only in the language of non-Arabs,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:52', 'QRTA:alusi:40-01', 52, 'as in Cain and Abel (قابيل وهابيل); this is transmitted from Sībawayh.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:53', 'QRTA:alusi:40-01', 53, 'In al-Kashf [it is said] that it is better to give as the cause definiteness (التعريف) and compounding (التركيب).', '[{"ar":"التَّعْرِيفِ","ref":"GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:54', 'QRTA:alusi:40-01', 54, 'Abū al-Sammāl read it with an i-vowel on the م (كسر), following the basic rule for two quiescent letters meeting (التقاء الساكنين), as in جير (‘yes, indeed’);', '[{"ar":"كَسْرِ","ref":"GT:irab_sign:kasra"},{"ar":"التِقاءِ السّاكِنَيْنِ","ref":"GT:phonotactic:iltiqa_sakinayn"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:55', 'QRTA:alusi:40-01', 55, 'and al-Zuhrī read it with the nominative ending (رفع), and apparently this is case inflection (إعراب): it is then either a subject (مبتدأ) or the predicate (خبر) of an omitted subject (مبتدأ محذوف). What is meant by it is discussed as are', '[{"ar":"رَفْعِها","ref":"GT:case:nominative"},{"ar":"مُبْتَدَأٌ","ref":"GT:irab_role:mubtada"},{"ar":"خَبَرُ","ref":"GT:irab_role:khabar"},{"ar":"مُبْتَدَأٍ","ref":"GT:irab_role:mubtada"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:56', 'QRTA:alusi:40-01', 56, 'its counterparts. It is pluralized as حواميم and حاميمات. As for the second, Ibn ʿAsākir cited for it in his History:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:57', 'QRTA:alusi:40-01', 57, '“This is the Messenger of God, among good things he came with ياسين and the حم surahs (حاميمات).” As for the first, several reports containing it have already passed, and I do not think that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:58', 'QRTA:alusi:40-01', 58, 'anyone would deny the soundness of all of them, or claim that the word حواميم in them is a corruption by non-Arab transmitters. Abū ʿUbayda also recited:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:59', 'QRTA:alusi:40-01', 59, '“I swore by the seven that were made long, / and by the hundreds after them that reached a hundred, / and by the eight that were doubled and repeated, / and by the طس surahs that were recited, / and by the حم surahs that were', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:60', 'QRTA:alusi:40-01', 60, 'made seven, / and by the closely divided surahs (المفصل) that were divided.” Al-Jawālīqī, al-Ḥarīrī and Ibn al-Jawzī held that one does not say حواميم. In al-Ṣiḥāḥ', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:61', 'QRTA:alusi:40-01', 61, 'it is reported from al-Farrāʾ that the common people''s saying الحواميم is not of the speech of the Arabs. The author of Zād al-Masīr reported from his teacher Abū Manṣūr', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:62', 'QRTA:alusi:40-01', 62, 'the lexicographer that it is a mistake to say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:63', 'QRTA:alusi:40-01', 63, '‘I read the حواميم’; the correct thing is to say ‘I read آل حم’. And in the report of Ibn Masʿūd: ‘When I come upon آل حم, I have', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:64', 'QRTA:alusi:40-01', 64, 'come upon soft, level meadows in which I delight.’ Along these lines is the saying of al-Kumayt ibn Zayd in al-Hāshimiyyāt:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:65', 'QRTA:alusi:40-01', 65, '“We found for you, in آل حم, a verse / which among us both the one who conceals and the one who speaks out have interpreted.” And الطواسين, and الطواسيم with م in place of ن, are likewise [rejected] in their view.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:66', 'QRTA:alusi:40-01', 66, 'What you have heard suffices to refute them.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:67', 'QRTA:alusi:40-01', 67, 'Admittedly, what they said is attested and accepted, like what we have said; but it should be known that آل in their saying آل حم is, as', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:68', 'QRTA:alusi:40-01', 68, 'al-Khafājī said, not in the well-known sense of آل, namely ‘family’; rather it is a word mentioned before what cannot properly be put in the dual (تثنية) or plural (جمع)', '[{"ar":"تَثْنِيَتُهُ","ref":"GT:number:dual"},{"ar":"جَمْعُهُ","ref":"GT:number:plural"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:69', 'QRTA:alusi:40-01', 69, 'among compound names (الأسماء المركبة) and the like, such as Taʾabbaṭa Sharran (تأبط شرا). When they want to put it in the dual or plural, and it is a sentence (جملة) in which that cannot be done, since', '[{"ar":"تَثْنِيَتَهُ","ref":"GT:number:dual"},{"ar":"جَمْعَهُ","ref":"GT:number:plural"},{"ar":"جُمْلَةٌ","ref":"GT:sentence_class:jumla"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:70', 'QRTA:alusi:40-01', 70, 'nothing like that is known in the speech of the Arabs, they add before it the word آل or ذوا, so one says:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:71', 'QRTA:alusi:40-01', 71, '‘آل تأبط شرا came to me’ or ‘ذوا تأبط شرا came to me’, meaning the two men or the men named by this name. So آل حم means', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:72', 'QRTA:alusi:40-01', 72, 'the حواميم, and آل has the sense of ذو (‘possessor of’); what is meant by it is whatever this word is applied to and used for, and it is a figurative usage (مجاز) for association in meaning.', '[{"ar":"مَجازٌ","ref":"GT:balagha_bayan:majaz"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:73', 'QRTA:alusi:40-01', 73, 'In the words of al-Raḍī and others there is an allusion to this, except that they did not state its explanation explicitly; so hold on to it. And it is reported in al-Kashf that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:74', 'QRTA:alusi:40-01', 74, 'it is better to pluralize it as ذوات حم, that is, rather than حواميم or حاميمات, and its meaning is ‘the surahs accompanied by this word’, I mean حم.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:75', 'QRTA:alusi:40-01', 75, '“The sending down of the Book is from God, the Almighty, the All-Knowing” (40:2): what is to be said about its grammatical analysis (إعراب) is like what was said at the opening of Sūrat al-Zumar, except that here it is also permissible', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:76', 'QRTA:alusi:40-01', 76, 'for “sending down” (تنزيل) to be a predicate (خبر) of the opening letters (حم). Perhaps the singling out of these two attributes is because of the inimitability (إعجاز) of the majestic Qurʾān and the kinds of', '[{"ar":"خَبَرًا","ref":"GT:irab_role:khabar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:77', 'QRTA:alusi:40-01', 77, 'knowledge in it which the compass of human understanding is too narrow to take in; or it is along the lines of the singling out of the two attributes in the earlier passage, for the hallmark of', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:78', 'QRTA:alusi:40-01', 78, 'one whose knowledge of things is far-reaching is that he be wise; except that “the All-Knowing” was said here rather than “the All-Wise” for the sake of stylistic variation (تفنن).', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:79', 'QRTA:alusi:40-01', 79, 'And His words, exalted is He: “Forgiver of sin and Accepter of repentance, severe in punishment, Possessor of bounty” (40:3) are adjectives (صفات) of the Majestic Name, like “the Almighty, the All-Knowing.” “Forgiver of sin, Accepter of', '[{"ar":"صِفاتٌ","ref":"GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:80', 'QRTA:alusi:40-01', 80, 'repentance, and Possessor of bounty” are mentioned to arouse hope and desire (الترغيب), and “severe in punishment” is mentioned to arouse fear (الترهيب); and all of them together serve to urge toward what is intended by “the sending down of the Book,” namely what is mentioned', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:81', 'QRTA:alusi:40-01', 81, 'after it: the affirmation of God’s oneness (التوحيد), belief in the resurrection, which entails belief in everything besides these two, and turning wholeheartedly to God, exalted is He. The first two of these epithets, even though they are', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:82', 'QRTA:alusi:40-01', 82, 'active participles (اسم فاعل), are not meant to convey renewal (التجدد) or restriction to a particular time; rather, they are meant to convey permanence and continuity (الثبوت والاستمرار). So their annexation to the definite noun (المعرفة) that follows them', '[{"ar":"فاعِلٍ","ref":"GT:derivation_type:active_participle"},{"ar":"لِلْمَعْرِفَةِ","ref":"GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:83', 'QRTA:alusi:40-01', 83, 'is a pure annexation (محضة), which has given them definiteness (تعريف); hence it is valid for the most definite of all definite nouns (أعرف المعارف) to be qualified by them. As for “Possessor of bounty,” the matter is perfectly clear.', '[{"ar":"مَحْضَةٌ","ref":"GT:idafa_kind:manawiya"},{"ar":"تَعْرِيفًا","ref":"GT:definiteness:definite"},{"ar":"المَعارِفِ","ref":"GT:definiteness:definite"},{"ar":"يُوصَفَ","ref":"GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:84', 'QRTA:alusi:40-01', 84, 'Yes, the matter of “severe in punishment” is problematic, for “severe” (شديد) is an adjective resembling the participle (صفة مشبهة), and Sībawayh stated explicitly that everything', '[{"ar":"صِفَةٌ مُشَبَّهَةٌ","ref":"GT:derivation_type:sifa_mushabbaha"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:85', 'QRTA:alusi:40-01', 85, 'whose annexation is not pure (إضافته غير محضة), when it is annexed to a definite noun (معرفة), may be intended to have its annexation become pure (التمحض), so that it becomes definite and a definite noun can be qualified (ينعت) by it, except', '[{"ar":"إضافَتُهُ غَيْرُ مَحْضَةٍ","ref":"GT:idafa_kind:lafziya"},{"ar":"مَعْرِفَةٍ","ref":"GT:definiteness:definite"},{"ar":"التَّمَحُّضُ","ref":"GT:idafa_kind:manawiya"},{"ar":"يُنْعَتُ","ref":"GT:irab_role:naat"},{"ar":"المَعْرِفَةُ","ref":"GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:86', 'QRTA:alusi:40-01', 86, 'what belongs to the category of the adjective resembling the participle (الصفة المشبهة), for that does not become definite. On this basis al-Zajjāj held that “severe in punishment”', '[{"ar":"الصِّفَةِ المُشَبَّهَةِ","ref":"GT:derivation_type:sifa_mushabbaha"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:87', 'QRTA:alusi:40-01', 87, 'is a substitute (بدل). Against this it is objected that placing a substitute in the middle of adjectives (الصفات) produces an obvious dissonance, because an adjective (الوصف) signals that the thing it qualifies (الموصوف) is the one intended,', '[{"ar":"بَدَلٌ","ref":"GT:irab_role:badal"},{"ar":"البَدَلِ","ref":"GT:irab_role:badal"},{"ar":"الصِّفاتِ","ref":"GT:irab_role:naat"},{"ar":"الوَصْفَ","ref":"GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:88', 'QRTA:alusi:40-01', 88, 'whereas the substitute (البدل) signals the opposite; so it would amount to making the qualified noun the object of intention afresh after it had been made not intended. The answer is that this is problematic, on the face of it, only according to the school of', '[{"ar":"البَدَلُ","ref":"GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:89', 'QRTA:alusi:40-01', 89, 'Sībawayh and the rest of the Basrans, who hold that the adjective resembling the participle (الصفة المشبهة) never becomes definite by annexation (الإضافة) to a definite noun (المعرفة); but according to the school of the Kufans, who hold', '[{"ar":"الصِّفَةَ المُشَبَّهَةَ","ref":"GT:derivation_type:sifa_mushabbaha"},{"ar":"بِالإضافَةِ","ref":"GT:balagha_maani:tarif_bil_idafa"},{"ar":"المَعْرِفَةِ","ref":"GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:90', 'QRTA:alusi:40-01', 90, 'that, like other adjectives (الصفات), it can become definite by annexation (الإضافة), and that a definite noun (المعرفة) may be qualified by it, as in “I passed by Zayd, the handsome-faced,” it is not problematic. And it may be said', '[{"ar":"الصِّفاتِ","ref":"GT:pos:sifa"},{"ar":"بِالإضافَةِ","ref":"GT:balagha_maani:tarif_bil_idafa"},{"ar":"المَعْرِفَةِ","ref":"GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:91', 'QRTA:alusi:40-01', 91, 'concerning what was mentioned, on the first school’s view:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:92', 'QRTA:alusi:40-01', 92, '“severe” (شديد) is to be interpreted as “one who makes severe” (مشدد), an active participle (اسم فاعل) from أشدّه, meaning “he made it severe,” just as أذين is used in the sense of مؤذن (“one who announces”); so it is given that word’s ruling. Or it may be said:', '[{"ar":"اسْمِ فاعِلٍ","ref":"GT:derivation_type:active_participle"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:93', 'QRTA:alusi:40-01', 93, 'it is made definite by the definite article (معرف بأل), the original being الشديد عقابه (“the One whose punishment is severe”), but the article was dropped (حذف) because there is no risk of confusing it with anything other than an adjective (الصفة), since it occurs among adjectives (الصفات); and the possibility of its being a substitute (بدل)', '[{"ar":"مُعَرَّفٌ بِألْ","ref":"GT:balagha_maani:tarif_bil_lam"},{"ar":"حُذِفَتْ","ref":"GT:balagha_maani:hadhf"},{"ar":"الصِّفَةِ","ref":"GT:pos:sifa"},{"ar":"الصِّفاتِ","ref":"GT:irab_role:naat"},{"ar":"بَدَلًا","ref":"GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:94', 'QRTA:alusi:40-01', 94, 'on its own is not to be heeded, as you have heard; and it was also dropped out of regard for conformity (مشاكلة) with the adjectives accompanying it, which are stripped of the article; and what is understood as implied (المقدر) has the status of', '[{"ar":"مُشاكَلَةِ","ref":"GT:balagha_badi:mushakala"},{"ar":"الأوْصافِ","ref":"GT:irab_role:naat"},{"ar":"المُقَدَّرُ","ref":"GT:irab_role:taqdir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:95', 'QRTA:alusi:40-01', 95, 'what is actually present. Indeed, they altered much of their speech from its rules for the sake of conformity (المشاكلة), so much so that they said:', '[{"ar":"المُشاكَلَةِ","ref":"GT:balagha_badi:mushakala"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:96', 'QRTA:alusi:40-01', 96, '“He does not know his سحادليه from his عنادليه,” meaning he does not know his male member from his two testicles; so they put into the dual what is single for the sake of what is', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:97', 'QRTA:alusi:40-01', 97, 'a pair. It has also been held permissible that all of the dependents (التوابع) mentioned are substitutes (أبدال), with “severe in punishment” deliberately left indefinite (تنكير) and vague (إبهام) to indicate extreme severity', '[{"ar":"أبْدالًا","ref":"GT:irab_role:badal"},{"ar":"تَنْكِيرَ","ref":"GT:balagha_maani:tankir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:98', 'QRTA:alusi:40-01', 98, 'and that nothing is more calamitous or more bitter than it, in order to intensify the warning.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:99', 'QRTA:alusi:40-01', 99, 'In al-Kashf: making them all substitutes (أبدال) involves great dissonance, especially in substituting “the Almighty” for “God,”', '[{"ar":"أبْدالًا","ref":"GT:irab_role:badal"},{"ar":"إبْدالِ","ref":"GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:100', 'QRTA:alusi:40-01', 100, 'the Name that comprises all the attributes, the proper name (العلم) that admits no other meaning; and what has this to do with the excellence of the opening (براعة الاستهلال)?', '[{"ar":"العَلَمِ","ref":"GT:pos:alam"},{"ar":"بَراعَةِ الِاسْتِهْلالِ","ref":"GT:balagha_badi:baraat_istihlal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:101', 'QRTA:alusi:40-01', 101, 'Makkī held it permissible for “Forgiver of sin and Accepter of repentance,” though not what precedes them, to be two substitutes (بدلين), in which case they are both indefinite (نكرتان). You already know', '[{"ar":"بَدَلَيْنِ","ref":"GT:irab_role:badal"},{"ar":"نَكِرَتانِ","ref":"GT:definiteness:indefinite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:102', 'QRTA:alusi:40-01', 102, 'what is wrong with this from what has preceded. Abū Ḥayyān said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:103', 'QRTA:alusi:40-01', 103, '“The substitute of change of mind (بدل البداء), according to those who accept it, may be repeated; but as for the whole-for-whole substitute (بدل كل من كل), the part-for-whole substitute (بدل بعض من كل), and the', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:104', 'QRTA:alusi:40-01', 104, 'substitute of inclusion (بدل اشتمال), I know of no explicit statement from any of the grammarians on whether repeating them is permitted or forbidden, except that in the words of', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:105', 'QRTA:alusi:40-01', 105, 'some of our colleagues there is what indicates that a substitute for a substitute (البدل من البدل) is permissible, but not multiple substitutes for a single antecedent (المبدل منه).” The apparent sense of the words of', '[{"ar":"البَدَلَ","ref":"GT:irab_role:badal"},{"ar":"البَدَلِ","ref":"GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:106', 'QRTA:alusi:40-01', 106, 'al-Khafājī is that the grammarians explicitly stated that multiple substitutes are permissible, for he said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:107', 'QRTA:alusi:40-01', 107, '“The view that they are substitutes (الإبدال) is not undermined by the rarity of substitutes (البدل) among derived nouns (المشتقات), nor by the rule that an indefinite noun (النكرة) is not substituted for a definite one (المعرفة) unless', '[{"ar":"الإبْدالِ","ref":"GT:irab_role:badal"},{"ar":"البَدَلِ","ref":"GT:irab_role:badal"},{"ar":"المُشْتَقّاتِ","ref":"GT:form_family:noun_derivatives"},{"ar":"النَّكِرَةَ","ref":"GT:definiteness:indefinite"},{"ar":"المَعْرِفَةِ","ref":"GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:108', 'QRTA:alusi:40-01', 108, 'it is qualified (توصف), nor by the claim, as some have made it, that the grammarians did not mention multiple substitutes (البدل), because the grammarians explicitly stated the contrary on all of these points. Al-Damāmīnī has on this', '[{"ar":"تُوصَفْ","ref":"GT:irab_role:naat"},{"ar":"البَدَلِ","ref":"GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:109', 'QRTA:alusi:40-01', 109, 'a long, drawn-out discussion at the beginning of his commentary on al-Khazrajiyya, for which there is no room here; if you want it, look there.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:110', 'QRTA:alusi:40-01', 110, 'End of quotation. In my view, substitution (الإبدال) here is of no account, whether for all of them or for some. “Repentance” (التوب) may be a verbal noun (مصدر), like أوب, meaning', '[{"ar":"الإبْدالَ","ref":"GT:irab_role:badal"},{"ar":"مَصْدَرًا","ref":"GT:derivation_type:masdar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:111', 'QRTA:alusi:40-01', 111, 'returning, or it may be a collective noun (اسم جمع) of توبة, like تمر (dates) and تمرة (a single date). “Bounty” (الطول) is favour shown through reward and the bestowal of blessings, or through that and through refraining from', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:112', 'QRTA:alusi:40-01', 112, 'the punishment that is deserved, as has been said; and this is better than restricting it to refraining from punishment, even though it comes after “severe in punishment.” The claim that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:113', 'QRTA:alusi:40-01', 113, 'reward, being promised, has become like something obligatory and so is not a favour, is of no account, for promising it is not itself obligatory. Ibn ʿAbbās explained it as abundance', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:114', 'QRTA:alusi:40-01', 114, 'and self-sufficiency, Qatāda as blessings, and Ibn Zayd as power. Placing “and” (الواو) between “Forgiver of sin and Accepter of repentance” serves to convey that the repentant sinner is granted, together,', '[{"ar":"الواوِ","ref":"GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:115', 'QRTA:alusi:40-01', 115, 'two mercies: that He, glorified is He, accepts his repentance and records it for him as one of the acts of obedience, and that He makes it an eraser of the sin, as though he had never sinned;', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:116', 'QRTA:alusi:40-01', 116, 'as though it were said: “the One who combines forgiveness and acceptance.” So said al-Zamakhsharī. Its rationale, as given in al-Kashf, is that adjectives (صفات) following one another without “and” (الواو) already indicate the sense of combination as such', '[{"ar":"الواوِ","ref":"GT:harf_maani:atf"},{"ar":"صِفاتٌ","ref":"GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:117', 'QRTA:alusi:40-01', 117, 'merely by being applied to the noun; so when one of the paired phrases is singled out with “and” (الواو), this shows that what is intended is the combination taken into account in it and in what precedes it specifically,', '[{"ar":"الواوِ","ref":"GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:118', 'QRTA:alusi:40-01', 118, 'so as to preserve the eloquent speaker’s words from being pointless. Thus the “and” (الواو) here indicates that He, glorified is He, combines forgiveness and the acceptance of repentance for the one who repents', '[{"ar":"الواوِ","ref":"GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:119', 'QRTA:alusi:40-01', 119, 'specifically. This does not conflict with the fact that He, mighty and majestic, may forgive one who has not repented. As for what has been said,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:120', 'QRTA:alusi:40-01', 120, 'namely that placing “and” in the middle indicates that the meaning is, as Abū al-Shaykh narrated in al-ʿAẓama from al-Ḥasan: “Forgiver of sin for one who has not', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:121', 'QRTA:alusi:40-01', 121, 'repented, and Accepter of repentance for one who has repented,” it is not conceded. And the difference they mention between where the two acts fall, namely forgiving the sin and accepting repentance', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:122', 'QRTA:alusi:40-01', 122, 'for it, which would require that forgiveness apply to one group and acceptance to others, since they made the object of the first the sin that remains in', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:123', 'QRTA:alusi:40-01', 123, 'the records without being punished, and the object of the second the sin that has been removed and erased from them, is already obtained by merely applying the epithets, so “and” (الواو) plays no part in it. Moreover, what', '[{"ar":"لِلْواوِ","ref":"GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:124', 'QRTA:alusi:40-01', 124, 'was mentioned in the earlier explanation holds on the principles of both the Sunnis (أهل السنة) and the Muʿtazilites, so there is no reason to reject it on grounds that do not impair it and to prefer what', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:125', 'QRTA:alusi:40-01', 125, 'is the weaker view. Placing (تقديم) “Forgiver” before “Accepter” belongs to the principle of putting the removal of faults before the adornment with virtues (التخلية على التحلية); so understand.', '[{"ar":"تَقْدِيمُ","ref":"GT:balagha_maani:taqdim_takhir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:126', 'QRTA:alusi:40-01', 126, 'On whether the acceptance of a sinner’s repentance is certain, the Sunnis have two views.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:127', 'QRTA:alusi:40-01', 127, 'In al-Baḥr: the apparent meaning of the verse is that the repentance of one who sinned by something other than unbelief, like the repentance of one who sinned by unbelief, is certain to be accepted. And in there being a single attribute of', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:128', 'QRTA:alusi:40-01', 128, 'punishment, engulfed by His attributes, exalted is He, that indicate mercy, there is evidence of the abundance of mercy and its precedence. So glory be to Him as God; how merciful He is, and how generous!', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:129', 'QRTA:alusi:40-01', 129, '“There is no god but He” (40:3); so total devotion to obeying Him in His commands and prohibitions is obligatory. “To Him is the final return” (40:3): to Him alone, not to anything other than Him,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:130', 'QRTA:alusi:40-01', 130, 'exalted is He, neither independently nor as a partner; and He will requite each one, the obedient and the disobedient. The clause “There is no god but He” is a new, independent clause (مستأنفة)', '[{"ar":"مُسْتَأْنَفَةٌ","ref":"GT:sentence_role:istinafiyya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:131', 'QRTA:alusi:40-01', 131, 'or a circumstantial clause (حالية); and it has been said:', '[{"ar":"حالِيَّةٌ","ref":"GT:sentence_role:hal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:132', 'QRTA:alusi:40-01', 132, 'it is an adjective (صفة) of “God,” exalted is He, or of “severe in punishment.” And these verses contain much that calls for taking heed.', '[{"ar":"صِفَةٌ","ref":"GT:sentence_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:133', 'QRTA:alusi:40-01', 133, 'ʿAbd ibn Ḥumayd narrated from Yazīd ibn al-Aṣamm that there was a man of great strength who was one of the people of Syria (الشام), and that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:134', 'QRTA:alusi:40-01', 134, 'ʿUmar, may God be pleased with him, missed him and asked about him, and he was told:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:135', 'QRTA:alusi:40-01', 135, '“He has given himself over to drink.” So ʿUmar called his scribe and said to him:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:136', 'QRTA:alusi:40-01', 136, '“Write: From ʿUmar ibn al-Khaṭṭāb to so-and-so son of so-and-so. Peace be upon you. I praise God to you, besides whom there is no god', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:137', 'QRTA:alusi:40-01', 137, 'but He. ‘In the name of God, the Most Merciful, the Most Compassionate. (حم)’, up to His words, exalted is He, ‘To Him is the final return.’” The letter was sealed, and he said', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:138', 'QRTA:alusi:40-01', 138, 'to his messenger: “Do not hand it to him until you find him sober.” Then he ordered those who were with him to pray that he would repent. When the letter reached him, he began reading it', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:139', 'QRTA:alusi:40-01', 139, 'and saying: “My Lord has promised me that He will forgive me, and has warned me of His punishment.” He kept repeating it to himself until he wept; then he gave it up, and gave it up', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:140', 'QRTA:alusi:40-01', 140, 'well. When news of his repentance reached ʿUmar, he said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:141', 'QRTA:alusi:40-01', 141, '“This is what you should do: when you see that your brother has slipped, set him right, steady him, and pray to God, exalted is He, to turn to him in forgiveness; and do not be', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:alusi:40-01:142', 'QRTA:alusi:40-01', 142, 'helpers of the devils against him.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:1', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 1, '“حم”: what is said about it is like what is said about its counterparts among the disconnected letters (الحروف المقطعة) at the openings of the surahs, and [the point] that after most of them comes mention of the Qur’an,', '[{"ar": "الحُرُوفِ المُقَطَّعَةِ", "ref": "GT:harf_maani:muqattaa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:2', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 2, 'and what that points to: challenging the deniers with their inability to produce anything to rival it.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:3', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 3, 'This has already been discussed at the opening of Surah al-Baqara, and we mentioned there that the letters whose names end in a long vowel followed by a glottal stop (ممدودة الآخر) are pronounced in', '[{"ar": "مَمْدُودَةُ الآخِرِ", "ref": "GT:noun_process:maqsur_mamdud"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:4', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 4, 'these openings in shortened form (مقصورة), dropping the glottal stop for lightness (حذف الهمزة تخفيفا), because they are in the state of pause (الوقف) — such as the name «حا» in this surah, the name «را»', '[{"ar": "مَقْصُورَةً", "ref": "GT:noun_process:maqsur_mamdud"}, {"ar": "حَذْفِ الهَمْزَةِ تَخْفِيفًا", "ref": "GT:phonotactic:takhfif_hamza"}, {"ar": "الوَقْفِ", "ref": "GT:phonotactic:waqf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:5', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 5, 'in «الر», and the name «يا» in «يس».', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:6', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 6, '“The sending down of the Book is from God, the Almighty, the All-Knowing”: what is said about it is like what is said on the opening of Surah al-Zumar.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:7', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 7, 'It is added here that those at whom this statement (الخبر) is aimed are the polytheists who deny that the Qur’an is sent down from God.', '[{"ar": "الخَبَرِ", "ref": "GT:balagha_maani:khabar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:8', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 8, 'So stripping the statement of any emphasizer (المؤكد) is presenting it contrary to what the apparent situation requires (خلاف مقتضى الظاهر), by treating the denier as a non-denier (جعل المنكر كغير المنكر), because there surround him', '[{"ar": "الخَبَرِ", "ref": "GT:balagha_maani:khabar"}, {"ar": "خِلافِ مُقْتَضى الظّاهِرِ", "ref": "GT:balagha_maani:mukhalafat_muqtada_zahir"}, {"ar": "جَعْلِ المُنْكِرِ كَغَيْرِ المُنْكِرِ", "ref": "GT:balagha_maani:tanzil_al_munkir_manzilat_ghayr_al_munkir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:9', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 9, 'proofs which, were he to reflect on them, would make him desist from his denial; so he had no right to deny that.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:10', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 10, '“Forgiver of sin, Accepter of repentance, severe in punishment, Possessor of power and bounty. There is no god but He; to Him is the final return.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:11', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 11, 'Six epithets (نعوت), all of them definite (معارف), are made to follow the name of God: some are definite through the definite article (حرف التعريف), and some through annexation (الإضافة) to a noun made definite by the article.', '[{"ar": "نُعُوتٍ", "ref": "GT:irab_role:naat"}, {"ar": "مَعارِفُ", "ref": "GT:definiteness:definite"}, {"ar": "حَرْفِ التَّعْرِيفِ", "ref": "GT:balagha_maani:tarif_bil_lam"}, {"ar": "بِالإضافَةِ", "ref": "GT:balagha_maani:tarif_bil_idafa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:12', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 12, 'Describing God here by the two attributes “the Almighty, the All-Knowing” is an indirect allusion (تعريض) that those who deny that the Book is sent down from Him are overpowered and subdued, and that God knows what', '[{"ar": "تَعْرِيضٌ", "ref": "GT:balagha_bayan:tarid"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:13', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 13, 'their souls conceal, so He will call them to account for it; and it is a subtle hint (رمز) that the Qur’an is the speech of the Almighty, the All-Knowing, so that none but God is able to produce', '[{"ar": "رَمْزٌ", "ref": "GT:balagha_bayan:kinaya_ramziyya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:14', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 14, 'anything like it, and none but God knows how to bring anything like it.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:15', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 15, 'This is the reason for the difference between this verse and its counterpart at the opening of Surah al-Zumar, where the attribute “the Almighty, the Wise” came — although', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:16', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 16, 'the description by knowledge allows what was allowed in some of the possible readings of the attribute “the Wise” in Surah al-Zumar.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:17', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 17, 'And the two attributes here also allow what was allowed there by way of the inimitability (إعجاز) of the Qur’an.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:18', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 18, 'And mentioning them is a subtle hint (رمز) that God knows best where to place His message, and that He does not go along with people’s whims about whom they put forward for it', '[{"ar": "رَمَزٌ", "ref": "GT:balagha_bayan:kinaya_ramziyya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:19', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 19, 'from among their great men: “And they said: Why was this Qur’an not sent down to a great man from the two towns?” [al-Zukhruf:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:20', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 20, '31]. And following the two great attributes with the attributes “Forgiver of sin, Accepter of repentance, severe in punishment, Possessor of power and bounty” is a reinforcement (ترشيح) of that indirect allusion (التعريض),', '[{"ar": "التَّعْرِيضِ", "ref": "GT:balagha_bayan:tarid"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:21', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 21, 'as if He were saying: If you have sinned by disbelieving in the Qur’an, then remedying your sin is within your power, because God’s being characterized by accepting repentance and forgiving sin is firmly established;', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:22', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 22, 'so just as He forgave those of the past nations who repented and accepted their faith, He will forgive whoever of you repents.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:23', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 23, 'Placing “Forgiver” before (تقديم) “Accepter of repentance”, even though forgiveness follows from it in occurrence, is out of concern (الاهتمام) to announce it without delay to whoever is ready to remedy', '[{"ar": "تَقْدِيمُ", "ref": "GT:balagha_maani:taqdim_takhir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:24', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 24, 'his situation. So the description “Forgiver of sin, Accepter of repentance” is an indirect allusion that encourages (الترغيب), and the two attributes “severe in punishment, Possessor of power and bounty” are an indirect allusion that warns (الترهيب).', '[{"ar": "تَعْرِيضٌ", "ref": "GT:balagha_bayan:tarid"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:25', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 25, 'التوب is the verbal noun (مصدر) of تاب (“he repented”); التوب with the two-dotted letter (ت), الثوب with the three-dotted letter (ث), and الأوب all mean returning — that is, returning to God’s command and obeying it after having moved away', '[{"ar": "مَصْدَرُ", "ref": "GT:derivation_type:masdar"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:26', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 26, 'from it. The attribute “and Accepter of repentance” was joined (عطفت) with “and” to the attribute “Forgiver of sin”, and was not left unjoined (تفصل) as the two attributes “the All-Knowing, Forgiver of sin” were left unjoined', '[{"ar": "عُطِفَتْ", "ref": "GT:irab_role:atf"}, {"ar": "تُفْصَلْ", "ref": "GT:balagha_maani:fasl"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:27', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 27, 'along with the attribute “severe in punishment”, only to point to a weighty subtle point: to convey that He combines for the repentant sinner two mercies — that He accepts', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:28', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 28, 'his repentance and makes it an act of obedience for him, and that by it He erases the sins he repented of and regretted committing, so that he becomes as though he', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:29', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 29, 'had never committed them. And this is a favour from God.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:30', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 30, 'His words “severe in punishment” openly disclose the threat against denying the Qur’an, because its coming after His words “The sending down of the Book is from God” [غافر:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:31', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 31, '2] conveys that this is what the speech is aiming at, by way of the secondary meanings that constructions entail (مستتبعات التراكيب).', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:32', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 32, 'What is meant by “Forgiver” and “Accepter” is that He is characterized by what they denote in what has passed, since the meaning is not that He will forgive and will accept; so the active participle (اسم الفاعل) in both', '[{"ar": "اسْمُ الفاعِلِ", "ref": "GT:derivation_type:active_participle"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:33', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 33, 'is cut off from resembling the verb and does not govern as the verb governs; therefore it acquires definiteness through annexation (التعريف بالإضافة), which brings it closer to nouns,', '[{"ar": "التَّعْرِيفَ بِالإضافَةِ", "ref": "GT:balagha_maani:tarif_bil_idafa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:34', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 34, 'and this is the reading that alone fits here.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:35', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 35, '“Severe” (شديد) is an adjective resembling the participle (صفة مشبهة), annexed to its agent (فاعل), and it has occurred as an epithet (نعت) of the name of God, on the view that the definiteness (التعريف) entering on the agent of the adjective stands', '[{"ar": "صِفَةٌ مُشَبَّهَةٌ", "ref": "GT:derivation_type:sifa_mushabbaha"}, {"ar": "فاعِلِ الصِّفَةِ", "ref": "GT:irab_role:fail"}, {"ar": "نَعْتًا", "ref": "GT:irab_role:naat"}, {"ar": "التَّعْرِيفَ", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:36', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 36, 'in place of the adjective’s own definiteness, so it does not depart from what is well established in the language: that the epithet and the noun it qualifies (النعت والمنعوت) agree in definiteness (التعريف). That the adjective resembling the participle', '[{"ar": "النَّعْتِ", "ref": "GT:irab_role:naat"}, {"ar": "التَّعْرِيفِ", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:37', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 37, 'acquires definiteness through annexation is the view of the Kufan grammarians, applying the rule of definiteness through annexation (التعريف بالإضافة) consistently; Sībawayh allows annexed adjectives to acquire definiteness through annexation', '[{"ar": "التَّعْرِيفَ بِالإضافَةِ", "ref": "GT:balagha_maani:tarif_bil_idafa"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:38', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 38, 'except the adjective resembling the participle (الصفة المشبهة), because its annexation is only to what is its agent in meaning, since the original status of what the adjective resembling the participle is annexed to is that it', '[{"ar": "الصِّفَةَ المُشَبَّهَةَ", "ref": "GT:derivation_type:sifa_mushabbaha"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:39', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 39, 'was its agent (فاعل), so annexing it to it is merely a lightening of the wording (تخفيف لفظي). And the matter is a minor one.', '[{"ar": "فاعِلًا", "ref": "GT:irab_role:fail"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:40', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 40, 'الطول is used for abundance of bounty and abundance of wealth, and it is used for power, as in al-Qāmūs, whose wording apparently applies it without restriction; and the author of Tāj', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:41', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 41, 'al-ʿArūs endorsed this and took it as the meaning in this verse. Its occurring together with “severe in punishment”, and their being paired with the two attributes “Forgiver of sin, Accepter of repentance”, is to point to', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:42', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 42, 'instilling fear of the punishment of the Hereafter through the attribute “severe in punishment”, and of the punishment of this world through the attribute “Possessor of power and bounty”, as in His words “Or We show you what We have promised them,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:43', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 43, 'for We have full power over them” [al-Zukhruf:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:44', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 44, '42], and His words “Say: God is able to send down a sign” [al-Anʿām:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:45', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 45, '37]. And He followed that with what indicates God’s oneness, and with the statement that the final return — that is, the place of return — is to Him, as a recorded verdict (تسجيل) on the falsity of associating partners with God and a refutation of their holding the resurrection to be impossible.', '[{"ar": "تَسْجِيلًا", "ref": "GT:balagha_maani:tasjil"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:46', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 46, 'So the sentence (جملة) “There is no god but He” stands in the position of an attribute (في موضع الصفة), and He followed it with the sentence “To Him is the final return” as a warning of the resurrection and the recompense,', '[{"ar": "جُمْلَةُ", "ref": "GT:sentence_class:jumla"}, {"ar": "مَوْضِعِ الصِّفَةِ", "ref": "GT:sentence_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:47', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 47, 'because, once the attributes “Forgiver of sin, Accepter of repentance, severe in punishment” had been applied, the speech stirred up both hope and fear, so it was fitting that', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:48', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 48, 'they be made aware that the final return is either to His reward or to His punishment, so let them weigh themselves in order to place themselves where their condition indicates.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:49', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 49, 'The fronting (تقديم) of the prepositional phrase (المجرور) in “To Him is the final return” is out of concern (الاهتمام) and to observe the verse-ending pattern (الرعاية على الفاصلة), which consists of two letters:', '[{"ar": "تَقْدِيُمُ", "ref": "GT:balagha_maani:taqdim_takhir"}, {"ar": "المَجْرُورِ", "ref": "GT:irab_role:jarr_majrur"}, {"ar": "رِّعايَةِ عَلى الفاصِلَةِ", "ref": "GT:balagha_badi:riayat_fasila"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:50', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 50, 'a soft letter (حرف لين) followed by a sound letter (حرف صحيح), as in:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:51', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 51, '“the All-Knowing” (العليم), “the lands” (البلاد), and “punishment” (عقاب).', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:52', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 52, 'The opening of this surah contains what points to the sum of its aims, what suits the discussion of the polytheists’ denial of the Qur’an, and what points', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:53', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 53, 'to their having taken pride in their strength and standing, and that this will pass away from them as it passed away from nations mightier than they; so this', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:ibn_ashur:y-m2kq2xlU4DM-02:54', 'QRTA:ibn_ashur:y-m2kq2xlU4DM-02', 54, 'opening has fully achieved what is sought in the openings of discourses, which is called “excellence of the opening” (براعة المطلع) or “excellence of the beginning” (براعة الاستهلال).', '[{"ar": "بَراعَةَ المَطْلَعِ", "ref": "GT:balagha_badi:baraat_istihlal"}, {"ar": "بَراعَةَ الِاسْتِهْلالِ", "ref": "GT:balagha_badi:baraat_istihlal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:1', 'QRTA:zamakhshari:40-01', 1, 'Meccan. Al-Ḥasan said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:2', 'QRTA:zamakhshari:40-01', 2, 'except His words “And glorify with the praise of your Lord”, because the prayers were revealed in Medina. And it has been said of all the surahs that open with «حم»:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:3', 'QRTA:zamakhshari:40-01', 3, 'that they are Meccan — reported from Ibn ʿAbbās and Ibn al-Ḥanafiyya. It has eighty-five verses; it is also said eighty-two. [Revealed after al-Zumar.] In the name of God, the Most Gracious,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:4', 'QRTA:zamakhshari:40-01', 4, 'the Most Merciful. It has been read with inclination (إمالة) of the long vowel of «حا» and with its full, uninclined pronunciation (تفخيم), and with the م made vowelless (تسكين) and with it given the vowel a (فتح).', '[{"ar": "بإمالة", "ref": "GT:phonotactic:imala"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:5', 'QRTA:zamakhshari:40-01', 5, 'The rationale for the a-vowel: either it is vowelling to avoid the meeting of two vowelless letters (التقاء الساكنين), choosing the lightest of the vowels, as in أين and كيف; or it is the accusative (النصب) through an implied “Recite” (إضمار), the word being barred from full declension (منع الصرف) because of feminine gender (التأنيث) and definiteness (التعريف), or', '[{"ar": "التقاء الساكنين", "ref": "GT:phonotactic:iltiqa_sakinayn"}, {"ar": "النصب", "ref": "GT:case:accusative"}, {"ar": "بإضمار", "ref": "GT:irab_role:idmar_al_amil"}, {"ar": "منع الصرف", "ref": "GT:noun_process:man_al_sarf"}, {"ar": "للتأنيث", "ref": "GT:gender:feminine"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:6', 'QRTA:zamakhshari:40-01', 6, 'because of definiteness and its being on the pattern of a foreign word, like قابيل (Cain) and هابيل (Abel).', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:7', 'QRTA:zamakhshari:40-01', 7, 'التوب, الثوب and الأوب:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:8', 'QRTA:zamakhshari:40-01', 8, 'are sisters in the meaning of returning. And الطول is bounty and increase.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:9', 'QRTA:zamakhshari:40-01', 9, 'One says: “So-and-so has طول over so-and-so.” And [it is] conferring favour:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:10', 'QRTA:zamakhshari:40-01', 10, 'one says: طال عليه and تطوّل, when he confers a favour.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:11', 'QRTA:zamakhshari:40-01', 11, 'If you ask: How do these attributes (الصفات) differ in definiteness and indefiniteness (تعريفا وتنكيرا), when the noun they describe (الموصوف) is definite (معرفة), which requires that its like be definite (معارف)?', '[{"ar": "الصفات", "ref": "GT:irab_role:naat"}, {"ar": "تعريفا", "ref": "GT:definiteness:definite"}, {"ar": "تنكيرا", "ref": "GT:definiteness:indefinite"}, {"ar": "معرفة", "ref": "GT:definiteness:definite"}, {"ar": "معارف", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:12', 'QRTA:zamakhshari:40-01', 12, 'I answer: As for “Forgiver of sin” and “Accepter of repentance”, both are definite (معرفتان), because what is meant by them is not the occurrence of the two actions — that He forgives sin and accepts repentance now', '[{"ar": "فمعرفتان", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:13', 'QRTA:zamakhshari:40-01', 13, 'or tomorrow — such that they would be taken as implicitly separated (تقدير الانفصال) and their annexation would therefore be non-genuine (إضافة غير حقيقية); rather what is meant is that this is established and permanent, so their status is', '[{"ar": "إضافتهما غير حقيقية", "ref": "GT:idafa_kind:lafziya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:14', 'QRTA:zamakhshari:40-01', 14, 'the status of “God of creation” and “Lord of the Throne”.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:15', 'QRTA:zamakhshari:40-01', 15, 'As for “severe in punishment”, its case is problematic, because it is understood as:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:16', 'QRTA:zamakhshari:40-01', 16, '“severe is His punishment” and cannot be detached from this underlying sense. Al-Zajjāj made it a substitute (بدل).', '[{"ar": "بدلا", "ref": "GT:irab_role:badal"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:17', 'QRTA:zamakhshari:40-01', 17, 'But its being a substitute (بدل) on its own among the attributes (الصفات) is plainly incongruous.', '[{"ar": "بدلا", "ref": "GT:irab_role:badal"}, {"ar": "الصفات", "ref": "GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:18', 'QRTA:zamakhshari:40-01', 18, 'The right view is to say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:19', 'QRTA:zamakhshari:40-01', 19, 'since this single indefinite (النكرة) has been met among these definites (المعارف), it announces that all of them are substitutes (أبدال), not attributes (أوصاف). An example of this is a poem', '[{"ar": "النكرة", "ref": "GT:definiteness:indefinite"}, {"ar": "المعارف", "ref": "GT:definiteness:definite"}, {"ar": "أبدال", "ref": "GT:irab_role:badal"}, {"ar": "أوصاف", "ref": "GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:20', 'QRTA:zamakhshari:40-01', 20, 'whose metrical feet all came on the measure مستفعلن: it is judged to be in the metre الرجز; but if a single foot in it came on', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:21', 'QRTA:zamakhshari:40-01', 21, 'متفاعلن, it would be in the metre الكامل. [[Maḥmūd (al-Zamakhsharī) said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:22', 'QRTA:zamakhshari:40-01', 22, '«If you ask: Why do these attributes (الصفات) differ in definiteness and indefiniteness (تعريفا وتنكيرا), when the noun they describe is definite (معرفة), which requires that its like be definite (معارف)?', '[{"ar": "الصفات", "ref": "GT:irab_role:naat"}, {"ar": "تعريفا", "ref": "GT:definiteness:definite"}, {"ar": "تنكيرا", "ref": "GT:definiteness:indefinite"}, {"ar": "معرفة", "ref": "GT:definiteness:definite"}, {"ar": "معارف", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:23', 'QRTA:zamakhshari:40-01', 23, 'He answered that “Forgiver of sin” and “Accepter of repentance” are definite (معرفان) because they are permanent attributes, not for the occurrence of the action such that they would refer to the present or the future;', '[{"ar": "معرفان", "ref": "GT:definiteness:definite"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:24', 'QRTA:zamakhshari:40-01', 24, 'rather, their annexation is genuine (إضافتهما حقيقة).', '[{"ar": "إضافتهما حقيقة", "ref": "GT:idafa_kind:manawiya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:25', 'QRTA:zamakhshari:40-01', 25, 'As for “severe in punishment”, there is no doubt that its annexation is non-genuine (إضافته غير حقيقية) — he means:', '[{"ar": "إضافته غير حقيقية", "ref": "GT:idafa_kind:lafziya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:26', 'QRTA:zamakhshari:40-01', 26, 'because it is one of the adjectives resembling the participle (الصفات المشبهة), whose annexation is never pure (محضة).', '[{"ar": "الصفات المشبهة", "ref": "GT:derivation_type:sifa_mushabbaha"}, {"ar": "إضافتها محضة", "ref": "GT:idafa_kind:manawiya"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:27', 'QRTA:zamakhshari:40-01', 27, 'His words resume; he said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:28', 'QRTA:zamakhshari:40-01', 28, 'Al-Zajjāj made it alone a substitute (بدل), and the substitute (البدل) standing alone among the attributes (الصفات) is plainly incongruous.', '[{"ar": "بدلا", "ref": "GT:irab_role:badal"}, {"ar": "البدل", "ref": "GT:irab_role:badal"}, {"ar": "الصفات", "ref": "GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:29', 'QRTA:zamakhshari:40-01', 29, 'The right view is to say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:30', 'QRTA:zamakhshari:40-01', 30, 'that all of them are substitutes (أبدال), not attributes (أوصاف), because of the occurrence of this indefinite (النكرة), which cannot validly be an attribute (صفة) — just as when a poem comes', '[{"ar": "أبدال", "ref": "GT:irab_role:badal"}, {"ar": "أوصاف", "ref": "GT:irab_role:naat"}, {"ar": "النكرة", "ref": "GT:definiteness:indefinite"}, {"ar": "صفة", "ref": "GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:31', 'QRTA:zamakhshari:40-01', 31, 'whose feet are all on مستفعل, it is judged to be in the metre الرجز; but if a single foot in it came on متفاعلن,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:32', 'QRTA:zamakhshari:40-01', 32, 'it would be in الكامل.» Aḥmad (Ibn al-Munayyir) said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:33', 'QRTA:zamakhshari:40-01', 33, 'This is because مستفعلن can enter الكامل, since متفاعلن becomes مستفعلن through the metrical change of making the second letter vowelless (الإضمار), whereas متفاعلن occurring in الرجز', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:34', 'QRTA:zamakhshari:40-01', 34, 'is not possible, since مستفعلن never turns into it at all; so whatever leads to reconciling the two is what must be adopted. This is like the jurists’ ruling', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:35', 'QRTA:zamakhshari:40-01', 35, 'of the specific over the general, because that is the way to reconcile two proofs.]] Someone might say:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:36', 'QRTA:zamakhshari:40-01', 36, 'they are attributes (صفات), and the definite article (الألف واللام) was dropped from “severe in punishment” only so that it would match in form what precedes and follows it; for they have changed much', '[{"ar": "صفات", "ref": "GT:irab_role:naat"}, {"ar": "الألف واللام", "ref": "GT:balagha_maani:tarif_bil_lam"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:37', 'QRTA:zamakhshari:40-01', 37, 'of their speech away from its rules for the sake of pairing (الازدواج), to the point that they said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:38', 'QRTA:zamakhshari:40-01', 38, '«ما يعرف سحادليه من عنادليه» (a saying meaning that he cannot tell one thing from another), making dual what is single for the sake of what is paired; moreover, al-Khalīl said about', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:39', 'QRTA:zamakhshari:40-01', 39, 'their saying «ما يحسن بالرجل مثلك أن يفعل ذلك» (“It does not befit a man like you to do that”) and «ما يحسن بالرجل خير منك أن يفعل» (“It does not befit a man better than you to do [it]”) that it is understood as having', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:40', 'QRTA:zamakhshari:40-01', 40, 'the definite article (الألف واللام), just as «الجماء الغفير» (“the great multitude”) is understood as having the definite article removed. What made this easy is that there is no risk of confusion or of not knowing', '[{"ar": "الألف واللام", "ref": "GT:balagha_maani:tarif_bil_lam"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:41', 'QRTA:zamakhshari:40-01', 41, 'the noun described. It may also be said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:42', 'QRTA:zamakhshari:40-01', 42, 'its indefiniteness (تنكيره) was deliberate, and its vagueness, to indicate extreme severity — something than which nothing is more calamitous or bitter — to strengthen the warning.', '[{"ar": "تنكيره", "ref": "GT:balagha_maani:tankir"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:43', 'QRTA:zamakhshari:40-01', 43, 'And it may be said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:44', 'QRTA:zamakhshari:40-01', 44, 'this subtle point is what calls for choosing the substitute (البدل) over the attribute (الوصف), if one takes the path of substitution.', '[{"ar": "البدل", "ref": "GT:irab_role:badal"}, {"ar": "الوصف", "ref": "GT:irab_role:naat"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:45', 'QRTA:zamakhshari:40-01', 45, 'If you ask: What is the point of the “and” (الواو) in His words “and Accepter of repentance”?', '[{"ar": "الواو", "ref": "GT:harf_maani:atf"}]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:46', 'QRTA:zamakhshari:40-01', 46, 'I answer: There is a weighty subtle point in it: conveying that He combines for the repentant sinner two mercies:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:47', 'QRTA:zamakhshari:40-01', 47, 'that He accepts his repentance and records it for him as one act of obedience among others,', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:48', 'QRTA:zamakhshari:40-01', 48, 'and that He makes it an eraser of sins, as though he had not sinned — as if He said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:49', 'QRTA:zamakhshari:40-01', 49, '“Combiner of forgiveness and acceptance.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:50', 'QRTA:zamakhshari:40-01', 50, 'It is narrated that ʿUmar, may God be pleased with him, missed a man of great valour from the people of Syria, and he was told:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:51', 'QRTA:zamakhshari:40-01', 51, 'He has given himself over to this drink. So ʿUmar said to his scribe:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:52', 'QRTA:zamakhshari:40-01', 52, 'Write: From ʿUmar to so-and-so:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:53', 'QRTA:zamakhshari:40-01', 53, 'Peace be upon you. I praise God to you, besides whom there is no god:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:54', 'QRTA:zamakhshari:40-01', 54, 'In the name of God, the Most Gracious, the Most Merciful:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:55', 'QRTA:zamakhshari:40-01', 55, '«حم» up to His words “To Him is the final return.”', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:56', 'QRTA:zamakhshari:40-01', 56, 'He sealed the letter and said to his messenger:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:57', 'QRTA:zamakhshari:40-01', 57, 'Do not hand it to him until you find him sober. Then he ordered those with him to pray for him that he repent.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:58', 'QRTA:zamakhshari:40-01', 58, 'When the letter reached him, he began reading it and saying:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:59', 'QRTA:zamakhshari:40-01', 59, 'God has promised me that He will forgive me, and has warned me of His punishment. He kept repeating it until he wept; then he gave it up, and gave it up well, and his repentance', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:60', 'QRTA:zamakhshari:40-01', 60, 'became sound. When ʿUmar heard of his affair, he said:', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:61', 'QRTA:zamakhshari:40-01', 61, 'This is what you should do: when you see that your brother has slipped, set him straight and support him, and pray to God for him that He turn to him in forgiveness, and do not be', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:62', 'QRTA:zamakhshari:40-01', 62, 'helpers of the devils against him. [[Abū Nuʿaym transmitted it in the biographical entry of Yazīd al-Aṣamm, through the narration of Kathīr ibn Hishām from Jaʿfar ibn', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:63', 'QRTA:zamakhshari:40-01', 63, 'Burqān from Yazīd al-Aṣamm: «A man was of great valour — and he cited it in full». ʿAbd ibn Ḥumayd narrated it in his Qur’an commentary from', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:64', 'QRTA:zamakhshari:40-01', 64, 'Kathīr ibn Hishām in abridged form.', '[]', 'live');
INSERT OR REPLACE INTO qr_tafsir_segment_en (segment_id, audio_id, seq, text_en, terms_json, status) VALUES ('SEG:QRTA:zamakhshari:40-01:65', 'QRTA:zamakhshari:40-01', 65, 'Likewise Ibn Abī Ḥātim and al-Thaʿlabī.]]', '[]', 'live');
